with x as (select * from jsonb_to_recordset('[{"linha": 4, "descricao": "RELÓGIO PONTO", "valor": 130.19, "vencimento": "2026-09-10", "previsao_pagamento": null, "forma_pagamento": "Boleto"}, {"linha": 5, "descricao": "HONORÁRIOS DO ESCRITÓRIO", "valor": 320, "vencimento": "2026-09-15", "previsao_pagamento": null, "forma_pagamento": "Pix"}, {"linha": 6, "descricao": "ESCRITÓRIO", "valor": 1800, "vencimento": "2026-09-15", "previsao_pagamento": null, "forma_pagamento": "Boleto"}, {"linha": 7, "descricao": "MEDICINA DO TRABALHO", "valor": 450, "vencimento": "2026-09-15", "previsao_pagamento": null, "forma_pagamento": "Boleto"}, {"linha": 8, "descricao": "ALUGUEL", "valor": 1100, "vencimento": "31/09/2026", "previsao_pagamento": null, "forma_pagamento": "Boleto"}, {"linha": 9, "descricao": "ÁGUA", "valor": 120, "vencimento": "31/09/2026", "previsao_pagamento": null, "forma_pagamento": "Boleto"}, {"linha": 10, "descricao": "INTERNET", "valor": 100, "vencimento": "31/09/2026", "previsao_pagamento": null, "forma_pagamento": "Boleto"}, {"linha": 11, "descricao": "2ª PARCELA - RAFAEL BARBOSA DOS SANTOS ", "valor": 1250, "vencimento": "2026-09-30", "previsao_pagamento": null, "forma_pagamento": "Pix"}]'::jsonb) as t(linha int,descricao text,valor numeric,vencimento text,previsao_pagamento text,forma_pagamento text)) insert into public.documentos_financeiros_importados(arquivo_nome,linha,tipo,dados,valor,vencimento,validacao) select 'Relatório Contas Pagar Julho.xlsx',linha,'contas_a_pagar',to_jsonb(x),valor,case when vencimento ~ '^\d{4}-\d{2}-\d{2}$' then vencimento::date end,case when vencimento ~ '^\d{4}-\d{2}-\d{2}$' then 'valido' else 'vencimento_invalido' end from x on conflict do nothing;
insert into public.financeiro_lancamentos(tipo,categoria,descricao,valor,vencimento,status,observacoes,empresa_id,fonte_documento)
select 'pagar','Contas a pagar',trim(x.descricao),x.valor,x.vencimento::date,'pendente','Fonte: Relatório Contas Pagar Julho.xlsx; forma: '||coalesce(x.forma_pagamento,'não informada'),'00000000-0000-0000-0000-000000000001','Relatório Contas Pagar Julho.xlsx'
from jsonb_to_recordset('[{"linha": 4, "descricao": "RELÓGIO PONTO", "valor": 130.19, "vencimento": "2026-09-10", "previsao_pagamento": null, "forma_pagamento": "Boleto"}, {"linha": 5, "descricao": "HONORÁRIOS DO ESCRITÓRIO", "valor": 320, "vencimento": "2026-09-15", "previsao_pagamento": null, "forma_pagamento": "Pix"}, {"linha": 6, "descricao": "ESCRITÓRIO", "valor": 1800, "vencimento": "2026-09-15", "previsao_pagamento": null, "forma_pagamento": "Boleto"}, {"linha": 7, "descricao": "MEDICINA DO TRABALHO", "valor": 450, "vencimento": "2026-09-15", "previsao_pagamento": null, "forma_pagamento": "Boleto"}, {"linha": 8, "descricao": "ALUGUEL", "valor": 1100, "vencimento": "31/09/2026", "previsao_pagamento": null, "forma_pagamento": "Boleto"}, {"linha": 9, "descricao": "ÁGUA", "valor": 120, "vencimento": "31/09/2026", "previsao_pagamento": null, "forma_pagamento": "Boleto"}, {"linha": 10, "descricao": "INTERNET", "valor": 100, "vencimento": "31/09/2026", "previsao_pagamento": null, "forma_pagamento": "Boleto"}, {"linha": 11, "descricao": "2ª PARCELA - RAFAEL BARBOSA DOS SANTOS ", "valor": 1250, "vencimento": "2026-09-30", "previsao_pagamento": null, "forma_pagamento": "Pix"}]'::jsonb) as x(linha int,descricao text,valor numeric,vencimento text,previsao_pagamento text,forma_pagamento text)
where x.vencimento ~ '^\d{4}-\d{2}-\d{2}$' and not exists (select 1 from public.financeiro_lancamentos f where f.fonte_documento='Relatório Contas Pagar Julho.xlsx' and f.descricao=trim(x.descricao) and f.vencimento=x.vencimento::date);
